head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBzProcsNo = "";
scwin.vListEligtyTpCd = "R";
scwin.selRow = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.fn_GetPar, scwin.fn_SetPar;
// mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.cm.InfoMenuID());
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.trsIdx; // insert, update 구분
scwin.fileType;
scwin.market = js_market;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        scwin.showLabel();
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        buttonSet.setInsertStatus();
        $c.elw.fn_searchCode();
        const sbmOptions = {
            id : "sbm_dts_Mst",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Mst=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        scwin.searchGrdCode("DELIST_REAL_INVSTG_RSN_CD", dtl_Grd1);
        scwin.searchGrdCode("LIST_ELIGTY_DELIB_RSLT_CD", dtl_Grd2);
        scwin.searchGrdCode("LIST_ELIGTY_DELIB_RSLT_CD", dtl_Grd3);
        scwin.searchGrdCode("LIST_ELIGTY_DELIB_RSLT_CD", dtl_Grd4);
        scwin.searchGrdCode("REAL_INVSTG_ABOL_LAWST_CD", dtl_Grd5);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05241.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05241.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("회사를 선택하세요");
        } else {
            scwin.initItem();
            await scwin.listSync();
            await scwin.listAllDtlSync("01", dts_Dtl1);
            await scwin.listAllDtlSync("02", dts_Dtl2);
            await scwin.listAllDtlSync("03", dts_Dtl3);
            await scwin.listAllDtlSync("04", dts_Dtl4);
            await scwin.listAllDtlSync("08", dts_Dtl5);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05241.btn_New_onclick" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadError
 * @description dts_Mst 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Mst_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Mst);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05241.dts_Mst_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05241.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        } else {
            buttonSet.setUpdateStatus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05241.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        scwin.initItem();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05241.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnClick = async function(row, colid) {
    try {
        await scwin.openDetail(row);
        await scwin.listAllDtlSync("01", dts_Dtl1, row);
        await scwin.listAllDtlSync("02", dts_Dtl2, row);
        await scwin.listAllDtlSync("03", dts_Dtl3, row);
        await scwin.listAllDtlSync("04", dts_Dtl4, row);
        await scwin.listAllDtlSync("08", dts_Dtl5, row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05241.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (scwin.trsIdx === TRS_IDX_DELETE) {
            scwin.callElasticFileNoti("DELETE");
        }
        const status = buttonSet.status;
        $c.lc.fn_alertMsg('S');
        await scwin.listSync();
        if (status === "U") {
            dts_List.setRowPosition(scwin.selRow, 0);
            await scwin.openDetail(scwin.selRow);
        } else {
            await scwin.openDetail(dts_List.getRowCount());
        }
        await scwin.afterFile();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05241.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
        // alert_error(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05241.trs_Save_OnFail" });
    }
};

