    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        if (chk_Yn.checked) {
            // 상장폐지기업 포함 모든 목록
            $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
        } else {
            $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
        }
        scwin.initItem();
        await scwin.listSync();
        await scwin.listAllDtlSync("01", dts_Dtl1);
        await scwin.listAllDtlSync("02", dts_Dtl2);
        await scwin.listAllDtlSync("03", dts_Dtl3);
        await scwin.listAllDtlSync("04", dts_Dtl4);
        await scwin.listAllDtlSync("08", dts_Dtl4);
