/**
 * @method
 * @name dtl_Grd2_OnPopup
 * @description dtl Grd2 On Popup 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} data 데이터
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dtl_Grd2_OnPopup = async function(row, colid, data) {
    try {
        if (colid === "ATTACH_FILE_CNT") {
            await scwin.attachFile(dts_Dtl2, row, "A");
        } else if (colid === "ATTACH_FILE_CNT2") {
            await scwin.attachFile(dts_Dtl2, row, "B");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05241.dtl_Grd2_OnPopup" });
    }
};

