/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    02549-상장폐지 실질심사 사유코드(10: 회생절차개시신청(삭제)  화면에서만 안보여달라고 함)
    03576 - 상장폐지실질심사기타코드
     */
    const arrCid = [{
        cid: "DELIST_REAL_INVSTG_RSN_CD",
        cnm: "cmb_DELIST_REAL_INVSTG_RSN_CD"
    }, {
        cid: "DELIST_REAL_INVSTG_MISC_CD",
        cnm: "cmb_DELIST_REAL_INVSTG_MISC_CD"
    }, {
        cid: "LIST_ELIGTY_DELIB_RSLT_CD",
        cnm: "cmb_LIST_ELIGTY_DELIB_RSLT_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    objCod = document.getElementById(arrCid[1].cnm);
    if (objCod === null) {
        await $c.win.alert(arrCid[1].cnm);
    }
    strCbd = "";
    for (j = 1; j <= dts_Cod.getRowCount(); j++) {
        if (dts_Cod.getCellData(j, "CD_ENG_NM") === "DELIST_REAL_INVSTG_MISC_CD") {
            // 상장폐지실질심사기타코드
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[1].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT").replace(/,/g, "','");
            }
        }
    }
    objCod.CBData = strCbd;
};

