/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요.");
        return false;
    }
    if (rdo_ClmDtlWebDpYn.getValue() === "") {
        await $c.win.alert("[웹반영여부]을 입력하세요.");
        rdo_ClmDtlWebDpYn.focus();
        return false;
    }
    if (med_ClmDtlWebDpDd.getValue() === "") {
        await $c.win.alert("[웹반영일]을 입력하세요.");
        med_ClmDtlWebDpDd.focus();
        return false;
    } else {
        if (!await scwin.eachDateCheck("[웹반영일]", med_ClmDtlWebDpDd)) {
            return false;
        }
    }
    if (!await scwin.eachDateCheck("2. 기업심사위원회 심의대상여부 결정 및 결정일자", edt_REAL_INVSTG_OBJ_DECSN_DD)) {
        return false;
    }
    if (!await scwin.eachDateCheck("3. 개선계획서 제출일", edt_IMPR_PLANDOC_SUBMIT_DD)) {
        return false;
    }
    if (!await scwin.eachDateCheck("6. 이의신청서 제출일", edt_EINSPRUCH_SUBMIT_DD)) {
        return false;
    }
    if (!await scwin.eachDateCheck("8. 정리매매기간 시작일", edt_ARRANTRD_STRT_DD)) {
        return false;
    }
    if (!await scwin.eachDateCheck("8. 정리매매기간 종료일", edt_ARRANTRD_END_DD)) {
        return false;
    }
    if (edt_ARRANTRD_STRT_DD.getValue() !== "" && edt_ARRANTRD_END_DD.getValue() !== "") {
        if (!$c.stf.compareFromToDate(edt_ARRANTRD_STRT_DD, edt_ARRANTRD_END_DD, "정리매매기간 시작일", "정리매매기간 종료일")) {
            return false;
        }
    }
    if (!await scwin.eachDateCheck("9. 상장폐지일", edt_DELIST_DD)) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name eachDateCheck
 * @description each Date Check 처리
 * @param {*} comment comment
 * @param {*} dateComponent dateComponent
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.eachDateCheck = async function(comment, dateComponent) {
    if (dateComponent.getText() !== "") {
        if (!scwin.checkDate(dateComponent.getText())) {
            await $c.win.alert(comment + " 날짜형식을 확인하세요");
            dateComponent.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name checkRsnVal
 * @description check Rsn Val 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkRsnVal = async function() {
    if (dts_Dtl1.getRowCount() === 0) {
        await $c.win.alert("실질심사 사유 및 사유발생일을 입력하세요.");
        return false;
    }
    let occrDd, imprDd = "";
    let isOkDate = true;
    for (j = 1; j <= dts_Dtl1.getRowCount(); j++) {
        if (dts_Dtl1.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") === "") {
            await $c.win.alert(j + "번째 [1. 실질심사 사유 및 사유발생일 '사유']를 입력하세요.");
            dtl_Grd1.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd1.focus();
            return false;
        }
        if (dts_Dtl1.getCellData(j, "OCCR_DD") === "") {
            await $c.win.alert(j + "번째 [1. 실질심사 사유 및 사유발생일 '일자']를 입력하세요.");
            dtl_Grd1.SetColumn("OCCR_DD");
            dtl_Grd1.focus();
            return false;
        }
        occrDd = dts_Dtl1.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [1. 실질심사 사유 및 사유발생일 '일자'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl2.getRowCount(); j++) {
        if (dts_Dtl2.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") === "" && dts_Dtl2.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") === "") {
            await $c.win.alert(j + "번째 [4. 기업심사위원회 심의 결과 및 결정일자 '결과']를 입력하세요.");
            dtl_Grd2.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd2.focus();
            return false;
        }
        if (dts_Dtl2.getCellData(j, "OCCR_DD") === "") {
            await $c.win.alert(j + "번째 [4. 기업심사위원회 심의 결과 및 결정일자 '일자']를 입력하세요.");
            dtl_Grd2.SetColumn("OCCR_DD");
            dtl_Grd2.focus();
            return false;
        }
        occrDd = dts_Dtl2.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [4. 기업심사위원회 심의 결과 및 결정일자 '일자'] 형식을 확인하세요.");
            return false;
        }
        imprDd = dts_Dtl2.getCellData(j, "IMPR_DEADLINE_DD");
        isOkDate = scwin.checkDate(imprDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [4. 기업심사위원회 심의 결과 및 결정일자 '개선기한'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl3.getRowCount(); j++) {
        let text = "5. 이의신청 前 코스닥시장위원회 심의·의결 결과 및 결정일자";
        if (scwin.market === "1") {
            text.setValue("5. 기업심사위원회(개선기간 종료) 심의·의결 결과 및 결정일자");
        }
        if (dts_Dtl3.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") === "" && dts_Dtl3.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") === "") {
            await $c.win.alert(j + "번째 [" + text + " '결과']를 입력하세요.");
            dtl_Grd3.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd3.focus();
            return false;
        }
        if (dts_Dtl3.getCellData(j, "OCCR_DD") === "") {
            await $c.win.alert(j + "번째 [" + text + " ' 일자']를 입력하세요.");
            dtl_Grd3.SetColumn("OCCR_DD");
            dtl_Grd3.focus();
            return false;
        }
        occrDd = dts_Dtl3.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [" + text + " '일자'] 형식을 확인하세요.");
            return false;
        }
        imprDd = dts_Dtl3.getCellData(j, "IMPR_DEADLINE_DD");
        isOkDate = scwin.checkDate(imprDd);
