        if (dts_Dtl4.getCellData(j, "OCCR_DD") === "") {
            await $c.win.alert(j + "번째 [" + text + " '일자']를 입력하세요.");
            dtl_Grd4.SetColumn("OCCR_DD");
            dtl_Grd4.focus();
            return false;
        }
        occrDd = dts_Dtl4.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [" + text + " '일자'] 형식을 확인하세요.");
            return false;
        }
        imprDd = dts_Dtl4.getCellData(j, "IMPR_DEADLINE_DD");
        isOkDate = scwin.checkDate(imprDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [" + text + " '개선기한'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl5.getRowCount(); j++) {
        let text = "10. 상장폐지 관련소송 결과 및 선고일자";
        if (dts_Dtl5.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") === "" && dts_Dtl5.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") === "") {
            await $c.win.alert(j + "번째 [" + text + " '결과']를 입력하세요.");
            dtl_Grd5.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd5.focus();
            return false;
        }
        if (dts_Dtl5.getCellData(j, "OCCR_DD") === "") {
            await $c.win.alert(j + "번째 [" + text + " '선고일자']를 입력하세요.");
            dtl_Grd5.SetColumn("OCCR_DD");
            dtl_Grd5.focus();
            return false;
        }
        occrDd = dts_Dtl5.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            await $c.win.alert(j + "번째 [" + text + " '선고일자'] 형식을 확인하세요.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (!await scwin.checkForm()) return;
    if (!await scwin.checkRsnVal()) return;
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Mst.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
        scwin.setBzProcsNo();
        await scwin.trs();
    }
};

/**
 * @method
 * @name setBzProcsNo
 * @description 신규 입력시 업무처리번호 셋팅
 * @param {*} bzProcsNo bzProcsNo
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(bzProcsNo) {
    const dtl1Row = dts_Dtl1.getRowCount();
    dts_Dtl1.setBroadcast(false);
    for (k = 1; k <= dts_Dtl1.getRowCount(); k++) {
        dts_Dtl1.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    dts_Dtl1.setBroadcast(true, true);
    dts_Dtl2.setBroadcast(false);
    for (k = 1; k <= dts_Dtl2.getRowCount(); k++) {
        dts_Dtl2.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    dts_Dtl2.setBroadcast(true, true);
    dts_Dtl3.setBroadcast(false);
    for (k = 1; k <= dts_Dtl3.getRowCount(); k++) {
        dts_Dtl3.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    dts_Dtl3.setBroadcast(true, true);
    dts_Dtl4.setBroadcast(false);
    for (k = 1; k <= dts_Dtl4.getRowCount(); k++) {
        dts_Dtl4.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    dts_Dtl4.setBroadcast(true, true);
    dts_Dtl5.setBroadcast(false);
    for (k = 1; k <= dts_Dtl5.getRowCount(); k++) {
        dts_Dtl5.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    dts_Dtl5.setBroadcast(true, true);
};

