 * @hidden N
 */
scwin.addRow = function(bnd, grid, type) {
    bnd.addRow();
    // grid.SetColumn("LIST_ELIGTY_PROCS_CD")
    grid.Focus();
    bnd.setCellData(bnd.getFocusedRowIndex(), "BZ_PROCS_NO", scwin.vBzProcsNo);
    if (type === "A") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "01");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "DELIST_REAL_INVSTG_RSN_CD");
    } else if (type === "B") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "02");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "LIST_ELIGTY_DELIB_RSLT_CD");
    } else if (type === "C") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "03");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "LIST_ELIGTY_DELIB_RSLT_CD");
    } else if (type === "D") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "04");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "LIST_ELIGTY_DELIB_RSLT_CD");
    } else if (type === "E") {
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_CD", "08");
        bnd.setCellData(bnd.getFocusedRowIndex(), "LIST_ELIGTY_PROCS_RSN_CD_VAL", "REAL_INVSTG_ABOL_LAWST_CD");
    }
};

