/**
 * @method
 * @name searchGrdCode
 * @description 코드값을 그리드 콤보박스에 설정
 * @param {*} codeName codeName
 * @param {*} grd grd
 * @returns {void}
 * @hidden N
 */
scwin.searchGrdCode = function(codeName, grd) {
    let strCbdReason = "' ':"; // 초기값
    for (k = 1; k <= dts_Cod.getRowCount(); k++) {
        if (dts_Cod.getCellData(k, "CD_ENG_NM") === codeName) {
            if (codeName === "DELIST_REAL_INVSTG_RSN_CD") {
                if (dts_Cod.getCellData(k, "VALUE") !== "10") {
                    strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
                }
            } else {
                strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
            }
        }
    }
    grd.setColumnProp('LIST_ELIGTY_PROCS_RSN_VAL', 'Data', strCbdReason);
};

/**
 * @method
 * @name attachFile
 * @description 첨부파일등록
 * @param {*} dataSet dataSet
 * @param {Number} row 행 인덱스
 * @param {*} type type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.attachFile = async function(dataSet, row, type) {
    scwin.fileType = type;
    if (dataSet.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ") === "") {
        await $c.win.alert("데이터를 저장 한 후, 파일을 등록하여 주십시오.");
    } else if (scwin.vBzProcsNo.length !== 14) {
        await $c.win.alert("심사  내용을 저장 한 후, 심의안건을 등록하여 주십시오.");
    } else {
        const procsCd = dataSet.getCellData(row, "LIST_ELIGTY_PROCS_CD");
        let dtlSeq = dataSet.getCellData(row, "LIST_ELIGTY_INVSTG_DTL_SEQ");
        let url = "/lstproc/ULDSTF05241_FILE.gfm?BZ_PROCS_NO=" + scwin.vBzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + procsCd + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq;
        if (type === "C") {
            url += "&LIST_ELIGTY_FILE_TP_CD=" + "07";
        } else if (type === "D") {
            url += "&LIST_ELIGTY_FILE_TP_CD=" + "08";
        }
        await $c.frame.CreateDialogFrame("FILE_ATTACH", url, "첨부파일 등록", 100, 100, 850, 450, "window");
    }
};

