/**
 * @method
 * @name checkDate
 * @description check Date 처리
 * @param {*} date date
 * @returns {void}
 * @hidden N
 */
scwin.checkDate = function(date) {
    let isOk = true;
    if (date.length > 0 && !$c.ut.isDate(date)) {
        isOk = false;
    }
    return isOk;
};

