/**
 * @method
 * @name grdFileDownload
 * @description grd File Download 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grdFileDownload = function(row, colid) {
    const bzProcsNo = dts_Dtl5.getCellData(row, "BZ_PROCS_NO");
    let pkString = "";
    if (colid === "ATTACH_FILE_NM1") {
        pkString = dts_Dtl5.getCellData(row, "ATTACH_FILE_NM1_PK");
    } else {
        pkString = dts_Dtl5.getCellData(row, "ATTACH_FILE_NM2_PK");
    }
    const procsNo = pkString.split("_")[0];
    let dtlSeq = pkString.split("_")[1];
    const fileSeq = pkString.split("_")[2];
    location.href = "/filedownload.do?SCREN_ID=" + "ULDSTF05241.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + procsNo + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq + "&ATTACH_FILE_SEQ=" + fileSeq + "&gubun=42";
};

